import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import BackButton from '../components/BackButton';
import LoadingSpinner from '../components/LoadingSpinner';
import { useApi } from '../contexts/ApiContext';
import { Studio } from '../services/api';

const StudioEdit: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { myStudio, loadMyStudio, updateStudio } = useApi();
  const [studio, setStudio] = useState<Studio | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    is_public: true
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchStudio = async () => {
      try {
        const studioId = parseInt(id || '0');

        // Load myStudio if not already loaded, or if it's a different ID
        if (!myStudio || myStudio.id !== studioId) {
          await loadMyStudio();
        }

        // Use myStudio if it matches, otherwise we'd need to load a specific studio
        const foundStudio = myStudio && myStudio.id === studioId ? myStudio : null;

        if (foundStudio) {
          setStudio(foundStudio);
          setFormData({
            name: foundStudio.name || '',
            description: foundStudio.description || '',
            is_public: foundStudio.is_public !== undefined ? foundStudio.is_public : true
          });
        } else {
          setError('Studio not found');
        }
      } catch (err) {
        setError('Failed to load studio');
        console.error('Error loading studio:', err);
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchStudio();
    }
  }, [id, myStudio, loadMyStudio]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaving(true);
    setError('');

    try {
      const studioId = parseInt(id || '0');
      const updateData: Partial<Studio> = {
        name: formData.name || '',
        description: formData.description || '',
        is_public: formData.is_public
      };

      const updatedStudio = await updateStudio(studioId, updateData);

      // Update local studio state
      setStudio(updatedStudio);

      navigate(`/immersivecomics/my-studio/`);
    } catch (err: any) {
      // Extract detailed error message from API response
      let errorMessage = 'An error occurred. Please try again.';
      if (err.response?.data) {
        // Handle Django REST Framework validation errors
        if (typeof err.response.data === 'object' && err.response.data !== null) {
          // Extract field errors
          const fieldErrors = Object.entries(err.response.data)
            .map(([field, messages]: [string, any]) => {
              let messageList: string;
              if (Array.isArray(messages) && messages.length > 0) {
                messageList = messages.join(', ');
              } else if (typeof messages === 'object' && messages !== null) {
                // Handle nested object errors
                messageList = JSON.stringify(messages);
              } else {
                messageList = String(messages);
              }
              return `${field}: ${messageList}`;
            })
            .join('; ');

          // Use field errors if available, otherwise check for detail/error keys
          if (fieldErrors.trim()) {
            errorMessage = fieldErrors;
          } else if (err.response.data.detail) {
            errorMessage = err.response.data.detail;
          } else if (err.response.data.error) {
            errorMessage = err.response.data.error;
          }
        } else {
          errorMessage = String(err.response.data);
        }
      } else if (err.message) {
        errorMessage = err.message;
      }
      setError(errorMessage);
      console.error('Studio update error:', {
        status: err.response?.status,
        data: err.response?.data,
        fullError: err
      });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <LoadingSpinner />;
  }

  if (error && !studio) {
    return (
      <div className="container mt-4" style={{ maxWidth: '800px' }}>
        <BackButton to="/immersivecomics/my-studio/" />
        <div className="alert alert-danger" role="alert">
          <i className="fas fa-exclamation-triangle me-2"></i>
          {error}
        </div>
      </div>
    );
  }

  return (
    <div className="container mt-4" style={{ maxWidth: '800px' }}>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h1 className="subtext-btn mb-0">
          <i className="fas fa-building me-2"></i>Edit Studio
        </h1>
        <BackButton />
      </div>

      <div className="card border-0 shadow-sm">
        <div className="card-body">
          {error && (
            <div className="alert alert-danger" role="alert">
              <i className="fas fa-exclamation-triangle me-2"></i>
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <div className="mb-3">
              <label htmlFor="name" className="form-label subtext-btn-sm">
                Studio Name <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                className="form-control"
                id="name"
                name="name"
                value={formData.name}
                onChange={handleChange}
                required
                placeholder="Enter studio name"
              />
            </div>

            <div className="mb-3">
              <label htmlFor="description" className="form-label subtext-btn-sm">
                Description
              </label>
              <textarea
                className="form-control"
                id="description"
                name="description"
                rows={4}
                value={formData.description}
                onChange={handleChange}
                placeholder="Enter studio description"
              />
            </div>

            <div className="mb-3">
              <div className="form-check">
                <input
                  className="form-check-input"
                  type="checkbox"
                  id="is_public"
                  name="is_public"
                  checked={formData.is_public}
                  onChange={handleChange}
                />
                <label className="form-check-label subtext-btn-sm" htmlFor="is_public">
                  Make studio public (visible to others)
                </label>
              </div>
            </div>

            <div className="d-flex gap-2 justify-content-end">
              <button
                type="button"
                className="btn btn-outline-secondary subtext-btn-sm"
                onClick={() => navigate(`/immersivecomics/my-studio/`)}
                disabled={saving}
              >
                Cancel
              </button>
              <button
                type="submit"
                className="btn btn-primary subtext-btn-sm"
                disabled={saving}
              >
                {saving ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    Saving...
                  </>
                ) : (
                  <>
                    <i className="fas fa-save me-2"></i>
                    &nbsp;Save
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default StudioEdit;
